/**
 * similar skill — "what's similar to X" (owner, 2026-10-21: "make them all easier to find"): for any skill that was combined into a family
 * (Mind Field, dates, games, time, languages and the rest), a card listing the family and every mode or sibling in it, each with an ask
 * that opens it. The index is lib/similar-index.js (generated by tools/similar-index.mjs from the family files' parts lines).
 * Contract: { name, examples, nearMisses, match(lower, text), run(text, api) }
 */
import INDEX from '../lib/similar-index.js';
const ASK = /^(?:what(?:'s| is| else is)? (?:similar to|like)|(?:show me |list )?(?:skills|things|modes) (?:like|similar to)|(?:what are )?(?:the )?(?:modes|parts) of|what (?:family|group) is) (?:the |a |an |your )?(.+?)(?: (?:in|part of))?(?: skill)?$/;
const CLEAN = (t) => String(t || '').toLowerCase().trim().replace(/[?!.]+$/, '').replace(/[’]/g, "'").replace(/\s+/g, ' ');
export const subjectOf = (text) => { const m = ASK.exec(CLEAN(text)); return m ? m[1].trim() : null; };
const title = (n) => n.replace(/-/g, ' ').replace(/^./, (c) => c.toUpperCase());

/** the family a subject names: by the family's name, a part's name, or one of a part's examples. Pure. */
export function findFamily(families, subject) {
  const s = String(subject || '').toLowerCase().replace(/\s+/g, '-'), plain = String(subject || '').toLowerCase();
  for (const [f, parts] of Object.entries(families || {})) {
    if (f === s || parts.some((p) => p.name === s || p.name === s + '-mind' || (p.examples || []).some((e) => e.toLowerCase() === plain))) return { family: f, parts, hit: (parts.find((p) => p.name === s || p.name === s + '-mind') || {}).name || null };
  }
  return null;
}

export default {
  name: 'similar',
  examples: ["what's similar to swarm mind", 'what is similar to the mind field', 'modes of mind field', 'what else is like the calendar', 'skills like nca mind'],
  nearMisses: ['what is similar to a crocodile', 'what is love like', 'what is it like to fly', 'modes of transport'],
  match(lower, text) { const s = subjectOf(text || lower); return !!s && !!findFamily(INDEX.families, s); }, // only a Verse skill's name: "what is similar to a crocodile" stays a page answer
  async run(text, api) {
    const subject = subjectOf(text); if (!subject) return 'none';
    const hit = findFamily(INDEX.families, subject);
    if (!hit) return 'none'; // not a Verse skill: leave it to the page answer ("what is similar to a crocodile")
    const name = hit.family === 'mind-field' ? 'Mind Field' : title(hit.family);
    api.showPage((p) => {
      p.innerHTML = '<h2>' + api.esc(name) + ': ' + hit.parts.length + ' combined</h2><p>' + api.esc(hit.hit ? title(hit.hit) + ' is one of these, all in one skill.' : 'These all live in one skill.') + ' Each ask below opens one.</p><ul class="similar-list">'
        + hit.parts.map((x) => '<li><b>' + api.esc(title(x.name)) + '</b>' + ((x.examples || []).length ? ': ' + x.examples.slice(0, 3).map((e) => '<a href="#" data-ask="' + api.esc(e) + '">' + api.esc(e) + '</a>').join(' · ') : '') + '</li>').join('') + '</ul>';
    });
    return 'similar';
  }
};
